"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[13732],{28453:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>r});var s=n(96540);const h={},a=s.createContext(h);function o(e){const t=s.useContext(a);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:o(e.components),s.createElement(a.Provider,{value:t},e.children)}},70166:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>r,default:()=>f,frontMatter:()=>o,metadata:()=>s,toc:()=>u});const s=JSON.parse('{"id":"tangfen/toflxdcsf4","title":"","description":"[Falanxi Dacai Shifu] just posted a new thread, and from it we can see why he has never understood Miss Chan\'s proof: he cannot distinguish the essential difference between human thought and computers! Computers must think and record character by character, number by number, but human thought doesn\'t need to. As the saying goes, \\"one thought encompasses three thousand worlds\\" -- this is the most essential difference between humans and computers.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/toflxdcsf4.md","sourceDirName":"tangfen","slug":"/tangfen/toflxdcsf4","permalink":"/en/tangfen/toflxdcsf4","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"toflxdcsf4","title":"","hide_table_of_contents":true},"sidebar":"tangfenSidebar","previous":{"title":"\u518d\u63d0\u4e00\u4e2a\u5efa\u8bae\uff0c\u5982\u53cd\u9a73\u9a6c\u514b\u601d\u3001\u7f20\u5973\u58eb\uff0c\u5148\u628a\u522b\u4eba\u7684\u601d\u60f3\u641e\u6e05\u695a\uff0c\u4e0d\u8981\u81ea\u5df1\u7f16\u9020\uff01","permalink":"/en/tangfen/anothersuggestion"},"next":{"title":"\u5ddd\u6d41\uff0c\u5728\u52b3\u52a8\u4ef7\u503c\u8bba\u7684\u95ee\u9898\u4e0a\uff0c\u8bf7\u4e0d\u8981\u628a\u9a6c\u514b\u601d\u6279\u5224\u7684\u89c2\u70b9\u52a0\u5728\u9a6c\u514b\u601d\u8eab\u4e0a\uff01","permalink":"/en/tangfen/tochuanliu"}}');var h=n(74848),a=n(28453);const o={id:"toflxdcsf4",title:"",hide_table_of_contents:!0},r="[Falanxi Dacai Shifu], Please Distinguish the Essential Difference Between Human Thought and Computers!",i={},u=[];function c(e){const t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.header,{children:(0,h.jsx)(t.h1,{id:"falanxi-dacai-shifu-please-distinguish-the-essential-difference-between-human-thought-and-computers",children:"[Falanxi Dacai Shifu], Please Distinguish the Essential Difference Between Human Thought and Computers!"})}),"\n",(0,h.jsx)(t.p,{children:"[Falanxi Dacai Shifu] just posted a new thread, and from it we can see why he has never understood Miss Chan's proof: he cannot distinguish the essential difference between human thought and computers! Computers must think and record character by character, number by number, but human thought doesn't need to. As the saying goes, \"one thought encompasses three thousand worlds\" -- this is the most essential difference between humans and computers."}),"\n",(0,h.jsx)(t.p,{children:"Let me first quote the relevant part of [Falanxi Dacai Shifu]'s post:"}),"\n",(0,h.jsx)(t.p,{children:"[Falanxi Dacai Shifu] posted on 2006-08-11 13:07:54"}),"\n",(0,h.jsxs)(t.p,{children:["--------------------------------------------------------------------------------",(0,h.jsx)("br",{})]}),"\n",(0,h.jsxs)(t.p,{children:['"If your mind truly cannot contemplate infinity, I can also briefly explain using the finite case.',(0,h.jsx)("br",{}),"\nIf the universe's lifespan is X, and the shortest interval for a human to think one character is Y, then the longest possible number of characters in human thought is N=X/Y.",(0,h.jsx)("br",{}),"\nMy previously mentioned super ultra-mega all-encompassing ultimate human encyclopedia totals just N volumes. It's finite.",(0,h.jsx)("br",{}),"\nUsing the Chan lady's formulation:",(0,h.jsx)("br",{}),"\nThe expression of this thought differs from A, the expression of this thought differs from B, the expression of this thought differs from C...",(0,h.jsx)("br",{}),"\nIt's very simple to see that the length of this expression must be greater than N, so it's not a human thought. Right?\""]}),"\n",(0,h.jsx)(t.p,{children:"Actually, this chef has himself revealed why he hasn't understood Miss Chan's proof. It's this sentence: \"Using the Chan lady's formulation: the expression of this thought differs from A, the expression of this thought differs from B, the expression of this thought differs from C... It's very simple to see that the length of this expression must be greater than N, so it's not a human thought. Right?\" Note: what needs to express human thought is the computer, not the human. \"Knowing that this expression's length must be greater than N, so it's not a human thought\" -- this statement shows the chef has confused human thought with computer expression."}),"\n",(0,h.jsx)(t.p,{children:"The chef, using the method Miss Chan used, derived that the characters expressing thoughts are finite. That's this sentence: \"If the universe's lifespan is X, and the shortest interval for a human to think one character is Y, then the longest possible number of characters in human thought is N=X/Y.\" But this precisely exposes the key reason he has never understood: human thinking doesn't need to proceed character by character! Because humans are not computers! Only computers need character-by-character expression! \"The shortest interval for a human to think one character\" -- this kind of question is meaningful only for computers, not for humans, because the recording mode of computers differs from the human brain. The human brain doesn't need to record character by character!"}),"\n",(0,h.jsx)(t.p,{children:"Of course, if this chef says his own brain works that way -- needing to record character by character to record anything -- that's his own business, and it has nothing to do with all of humanity. The human brain is not a computer. Computers cannot replace the human brain. The thinking mode of the human brain is essentially different from that of computers. This is something those who try to turn human brains into computers need to remember!"})]})}function f(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(c,{...e})}):c(e)}}}]);